// HCA 201A Day 3 PowerPoint. Question IDs and coverage terms are stable across edits.
const day3Questions = [
  {"id":"hca201a-day3-01-01","scope":"day3","topic":"Anatomical directions & planes","term":"Sagittal plane","prompt":"Which plane divides the body into left and right portions?","answer":"Sagittal","distractors":["Coronal","Transverse","Oblique"],"meaning":"A sagittal section separates left from right. A midsagittal section divides them equally.","source":"Day 3 PowerPoint · slide 1"},
  {"id":"hca201a-day3-01-02","scope":"day3","topic":"Anatomical directions & planes","term":"Coronal plane","prompt":"Which plane separates the front of the body from the back?","answer":"Coronal","distractors":["Sagittal","Midsagittal","Transverse"],"meaning":"Coronal, also called frontal, divides anterior from posterior.","source":"Day 3 PowerPoint · slide 1"},
  {"id":"hca201a-day3-01-03","scope":"day3","topic":"Anatomical directions & planes","term":"Transverse plane","prompt":"A scan shows a horizontal slice through the waist. Which plane is it in?","answer":"Transverse","distractors":["Sagittal","Coronal","Oblique"],"meaning":"The transverse plane divides the body into upper and lower portions.","source":"Day 3 PowerPoint · slide 1"},
  {"id":"hca201a-day3-02-01","scope":"day3","topic":"Body cavities","term":"Cranial cavity","prompt":"Which cavity lies within the skull and houses the brain?","answer":"Cranial","distractors":["Vertebral","Thoracic","Pelvic"],"meaning":"The skull encloses the cranial cavity and protects the brain.","source":"Day 3 PowerPoint · slide 2"},
  {"id":"hca201a-day3-02-02","scope":"day3","topic":"Body cavities","term":"Lungs and heart","prompt":"Which cavity contains both lungs and the heart?","answer":"Thoracic","distractors":["Cranial","Abdominal","Pelvic"],"meaning":"The lungs occupy pleural compartments in the thorax, with the heart between them.","source":"Day 3 PowerPoint · slide 2"},
  {"id":"hca201a-day3-02-03","scope":"day3","topic":"Body cavities","term":"Esophagus and trachea","prompt":"Which pair passes through part of the thorax on its way toward the stomach or lungs?","answer":"Esophagus and trachea","distractors":["Ureters and urethra","Rectum and sigmoid colon","Larynx and pharynx"],"meaning":"The esophagus and trachea have thoracic portions. The larynx is in the neck.","source":"Day 3 PowerPoint · slide 2"},
  {"id":"hca201a-day3-02-04","scope":"day3","topic":"Body cavities","term":"Larynx location","prompt":"Where is the larynx relative to the thorax?","answer":"In the neck, above the trachea","distractors":["In the chest, between the lungs","Below the diaphragm, beside the stomach","In the pelvis, below the bladder"],"meaning":"The slide groups the larynx with thoracic structures. The larynx is in the neck and connects to the trachea.","source":"Day 3 PowerPoint · slide 2","reference":{"label":"Cleveland Clinic","url":"https://my.clevelandclinic.org/health/body/21872-larynx"}},
  {"id":"hca201a-day3-02-05","scope":"day3","topic":"Body cavities","term":"Diaphragm","prompt":"What separates the thoracic cavity from the abdominal cavity?","answer":"Diaphragm","distractors":["Peritoneum","Pelvic floor","Sternum"],"meaning":"The diaphragm forms the floor of the thoracic cavity and the roof of the abdominal cavity.","source":"Day 3 PowerPoint · slide 2"},
  {"id":"hca201a-day3-02-06","scope":"day3","topic":"Body cavities","term":"Abdominal contents","prompt":"Which group is in the abdominal region?","answer":"Most digestive organs, the spleen, and the kidneys","distractors":["The heart, lungs, and thoracic trachea","The bladder, rectum, and pelvic reproductive organs","The brain, cerebellum, and brainstem"],"meaning":"The kidneys are in the abdominal region behind the peritoneum. The spleen and many digestive organs are also in the abdomen.","source":"Day 3 PowerPoint · slide 2"},
  {"id":"hca201a-day3-02-07","scope":"day3","topic":"Body cavities","term":"Pelvic urinary and reproductive structures","prompt":"Where are the resting urinary bladder and internal pelvic reproductive organs found?","answer":"Pelvic cavity","distractors":["Thoracic cavity","Cranial cavity","Spinal cavity"],"meaning":"The pelvic cavity is the lower part of the abdominopelvic cavity.","source":"Day 3 PowerPoint · slide 2"},
  {"id":"hca201a-day3-02-08","scope":"day3","topic":"Body cavities","term":"Appendix and cecum","prompt":"Which structures does the slide group with the lower right abdominopelvic region?","answer":"Appendix and cecum","distractors":["Spleen and stomach","Rectum and sigmoid colon","Liver and gallbladder"],"meaning":"The appendix attaches to the cecum. Their exact positions can vary, especially the position of the appendix.","source":"Day 3 PowerPoint · slide 2"},
  {"id":"hca201a-day3-02-09","scope":"day3","topic":"Body cavities","term":"Sigmoid colon and rectum","prompt":"Which parts of the large intestine are associated with the pelvis?","answer":"Sigmoid colon and rectum","distractors":["Cecum and ascending colon","Ascending and transverse colon","Transverse and descending colon"],"meaning":"The sigmoid colon leads into the rectum, which runs through the pelvis.","source":"Day 3 PowerPoint · slide 2"},
  {"id":"hca201a-day3-02-10","scope":"day3","topic":"Body cavities","term":"Abdominopelvic cavity","prompt":"What does the abdominopelvic cavity include?","answer":"Both the abdominal and pelvic cavities","distractors":["The thoracic and cranial cavities","Only the space between the peritoneal layers","Only the space behind the peritoneum"],"meaning":"The abdominopelvic cavity is the larger region containing the abdominal and pelvic subdivisions.","source":"Day 3 PowerPoint · slide 2"},
  {"id":"hca201a-day3-02-11","scope":"day3","topic":"Body cavities","term":"Peritoneal cavity","prompt":"Which statement correctly distinguishes the peritoneal cavity from the abdominopelvic cavity?","answer":"The peritoneal cavity is the potential space between the peritoneal layers.","distractors":["The two terms refer to every structure below the diaphragm.","The peritoneal cavity is the region behind the peritoneum.","The peritoneal cavity is the subdivision above the diaphragm."],"meaning":"The slide groups these terms. In anatomy, the peritoneal cavity is the potential space between the two layers of peritoneum.","source":"Day 3 PowerPoint · slide 2","reference":{"label":"OpenStax","url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/1-6-anatomical-terminology"}},
  {"id":"hca201a-day3-03-01","scope":"day3","topic":"Body cavities","term":"Retroperitoneal location","prompt":"Where is the retroperitoneal space?","answer":"Behind the peritoneum","distractors":["Between the two layers of peritoneum","In the space around the heart","Within the vertebral canal"],"meaning":"Retro- means behind. Retroperitoneal structures lie behind the lining of the abdominal wall.","source":"Day 3 PowerPoint · slide 3"},
  {"id":"hca201a-day3-03-02","scope":"day3","topic":"Body cavities","term":"Retroperitoneal organs","prompt":"Which group lies behind the abdominal peritoneum?","answer":"Kidneys, adrenal glands, and abdominal ureters","distractors":["Stomach, spleen, and jejunum","Heart, lungs, and trachea","Urinary bladder and internal pelvic reproductive organs"],"meaning":"The kidneys, adrenal glands, and abdominal portions of the ureters are retroperitoneal.","source":"Day 3 PowerPoint · slide 3"},
  {"id":"hca201a-day3-03-03","scope":"day3","topic":"Body cavities","term":"Bladder and peritoneum","prompt":"How is the resting urinary bladder usually described in relation to the peritoneum?","answer":"Below the peritoneum in the pelvis","distractors":["Suspended within the peritoneal cavity","Behind the abdominal peritoneum beside the kidneys","Over the diaphragm within the thorax"],"meaning":"The slide includes the bladder in its retroperitoneal list. The pelvic bladder is more precisely described as subperitoneal.","source":"Day 3 PowerPoint · slide 3","reference":{"label":"Radiopaedia","url":"https://radiopaedia.org/articles/extraperitoneal-space"}},
  {"id":"hca201a-day3-03-04","scope":"day3","topic":"Body cavities","term":"Vertebral canal","prompt":"Which space is formed by the vertebrae and contains the spinal cord?","answer":"Spinal cavity","distractors":["Cranial cavity","Thoracic cavity","Abdominal cavity"],"meaning":"The spinal cavity, or vertebral canal, runs through the vertebral column.","source":"Day 3 PowerPoint · slide 3"},
  {"id":"hca201a-day3-03-05","scope":"day3","topic":"Body cavities","term":"Dorsal cavity","prompt":"Which two cavities make up the dorsal or posterior body cavity?","answer":"Cranial and spinal","distractors":["Thoracic and abdominal","Abdominal and pelvic","Thoracic and pelvic"],"meaning":"The dorsal cavity is on the back side and contains the brain and spinal cord.","source":"Day 3 PowerPoint · slide 3"},
  {"id":"hca201a-day3-03-06","scope":"day3","topic":"Body cavities","term":"Ventral cavity","prompt":"Which two main spaces make up the ventral or anterior body cavity?","answer":"Thoracic and abdominopelvic","distractors":["Cranial and spinal","Cranial and thoracic","Spinal and pelvic"],"meaning":"The ventral cavity is on the front side and includes the chest, abdomen, and pelvis.","source":"Day 3 PowerPoint · slide 3"},
  {"id":"hca201a-day3-04-01","scope":"day3","topic":"Anatomical directions & planes","term":"Superior (cranial)","prompt":"How is the nose positioned relative to the mouth?","answer":"Superior","distractors":["Inferior","Lateral","Posterior"],"meaning":"Superior, or cranial in the figure, means toward the head.","source":"Day 3 PowerPoint · slide 4"},
  {"id":"hca201a-day3-04-02","scope":"day3","topic":"Anatomical directions & planes","term":"Inferior (caudal)","prompt":"How is the chin positioned relative to the nose?","answer":"Inferior","distractors":["Superior","Medial","Posterior"],"meaning":"Inferior, or caudal in the figure, means toward the lower end of the body.","source":"Day 3 PowerPoint · slide 4"},
  {"id":"hca201a-day3-04-03","scope":"day3","topic":"Anatomical directions & planes","term":"Anterior","prompt":"The sternum is in front of the heart. Which term describes that relationship?","answer":"Anterior","distractors":["Posterior","Superior","Inferior"],"meaning":"Anterior means toward the front.","source":"Day 3 PowerPoint · slide 4"},
  {"id":"hca201a-day3-04-04","scope":"day3","topic":"Anatomical directions & planes","term":"Posterior","prompt":"The spine is behind the sternum. Which term describes that relationship?","answer":"Posterior","distractors":["Anterior","Lateral","Inferior"],"meaning":"Posterior means toward the back.","source":"Day 3 PowerPoint · slide 4"},
  {"id":"hca201a-day3-04-05","scope":"day3","topic":"Anatomical directions & planes","term":"Lateral","prompt":"How are the ears positioned relative to the nose?","answer":"Lateral","distractors":["Medial","Inferior","Anterior"],"meaning":"Lateral means farther from the body's midline.","source":"Day 3 PowerPoint · slide 4"},
  {"id":"hca201a-day3-04-06","scope":"day3","topic":"Anatomical directions & planes","term":"Medial","prompt":"How is the nose positioned relative to the eyes?","answer":"Medial","distractors":["Lateral","Posterior","Superior"],"meaning":"Medial means closer to the body's midline.","source":"Day 3 PowerPoint · slide 4"},
  {"id":"hca201a-day3-05-01","scope":"day3","topic":"Cells, tissues & organs","term":"Cell","prompt":"What is the basic structural unit of the body?","answer":"Cell","distractors":["Tissue","Organ","System"],"meaning":"Cells are the basic units that form body tissues.","source":"Day 3 PowerPoint · slide 5"},
  {"id":"hca201a-day3-05-02","scope":"day3","topic":"Cells, tissues & organs","term":"Cytoplasm","prompt":"Which label identifies the material inside the cell surrounding the nucleus?","answer":"Cytoplasm","distractors":["Nuclear membrane","Cell membrane","Ribosomes"],"meaning":"The cytoplasm occupies the area within the cell membrane and outside the nucleus.","source":"Day 3 PowerPoint · slide 5"},
  {"id":"hca201a-day3-05-03","scope":"day3","topic":"Cells, tissues & organs","term":"Nucleus","prompt":"Which labelled cell structure houses most of the cell's DNA?","answer":"Nucleus","distractors":["Cytoplasm","Cell membrane","Ribosomes"],"meaning":"The nucleus contains most of the cell's genetic material.","source":"Day 3 PowerPoint · slide 5"},
  {"id":"hca201a-day3-05-04","scope":"day3","topic":"Cells, tissues & organs","term":"Nuclear membrane","prompt":"Which boundary encloses the nucleus?","answer":"Nuclear membrane","distractors":["Cell membrane","Cytoplasm","Ribosomes"],"meaning":"The nuclear membrane, also called the nuclear envelope, separates the nucleus from the cytoplasm.","source":"Day 3 PowerPoint · slide 5"},
  {"id":"hca201a-day3-05-05","scope":"day3","topic":"Cells, tissues & organs","term":"Cell membrane","prompt":"Which boundary encloses the entire cell?","answer":"Cell membrane","distractors":["Nuclear membrane","Cytoplasm","Nucleus"],"meaning":"The cell membrane forms the outer boundary and helps control movement into and out of the cell.","source":"Day 3 PowerPoint · slide 5"},
  {"id":"hca201a-day3-05-06","scope":"day3","topic":"Cells, tissues & organs","term":"Ribosomes","prompt":"The diagram points to small dots in the cell. Which labelled structures make proteins?","answer":"Ribosomes","distractors":["Nuclear membrane","Cell membrane","Nucleus"],"meaning":"Ribosomes assemble proteins.","source":"Day 3 PowerPoint · slide 5"},
  {"id":"hca201a-day3-06-01","scope":"day3","topic":"Cells, tissues & organs","term":"Tissue formation","prompt":"What do groups of cells with similar functions form?","answer":"Tissues","distractors":["Organs","Organ systems","Body cavities"],"meaning":"Groups of cells working together on similar functions form tissues.","source":"Day 3 PowerPoint · slide 6"},
  {"id":"hca201a-day3-06-02","scope":"day3","topic":"Cells, tissues & organs","term":"Epithelial tissue","prompt":"Which tissue covers body surfaces and lines internal surfaces?","answer":"Epithelial","distractors":["Connective","Muscle","Nervous"],"meaning":"The skin's surface and the lining of many internal spaces are examples of epithelium.","source":"Day 3 PowerPoint · slide 6"},
  {"id":"hca201a-day3-06-03","scope":"day3","topic":"Cells, tissues & organs","term":"Connective tissue","prompt":"Which tissue anchors, connects, and supports other tissues?","answer":"Connective","distractors":["Epithelial","Muscle","Nervous"],"meaning":"Connective tissue provides support and binds structures together.","source":"Day 3 PowerPoint · slide 6"},
  {"id":"hca201a-day3-06-04","scope":"day3","topic":"Cells, tissues & organs","term":"Muscle tissue","prompt":"Which tissue contracts to produce movement and can stretch as movement occurs?","answer":"Muscle","distractors":["Connective","Epithelial","Nervous"],"meaning":"Muscle contraction produces movement, while muscle tissue can stretch as body parts change position.","source":"Day 3 PowerPoint · slide 6"},
  {"id":"hca201a-day3-06-05","scope":"day3","topic":"Cells, tissues & organs","term":"Nervous tissue","prompt":"Which tissue carries impulses to and from the brain and throughout the body?","answer":"Nervous","distractors":["Muscle","Connective","Epithelial"],"meaning":"Nervous tissue receives and transmits signals throughout the body.","source":"Day 3 PowerPoint · slide 6"},
  {"id":"hca201a-day3-07-01","scope":"day3","topic":"Cells, tissues & organs","term":"Organ formation","prompt":"What do different tissues form when they work together in one structure?","answer":"An organ","distractors":["An organ system","A cell","A body cavity"],"meaning":"An organ contains multiple tissue types working together.","source":"Day 3 PowerPoint · slide 7"},
  {"id":"hca201a-day3-07-02","scope":"day3","topic":"Cells, tissues & organs","term":"Organ system formation","prompt":"What forms when several organs work together to perform a special function?","answer":"An organ system","distractors":["A tissue","A cell","A body cavity"],"meaning":"The stomach, intestines, and other organs work together in the digestive system.","source":"Day 3 PowerPoint · slide 7"},
  {"id":"hca201a-day3-07-03","scope":"day3","topic":"Cells, tissues & organs","term":"Homeostasis","prompt":"What is the name for keeping the body's internal conditions relatively stable?","answer":"Homeostasis","distractors":["Metastasis","Inflammation","Cell division"],"meaning":"Organ systems work together to maintain conditions such as body temperature and fluid balance.","source":"Day 3 PowerPoint · slide 7"},
  {"id":"hca201a-day3-07-04","scope":"day3","topic":"Cells, tissues & organs","term":"Levels of organization example","prompt":"Which sequence matches the example on the slide from simplest to most complex?","answer":"Muscle cell → muscle tissue → stomach → digestive system","distractors":["Muscle tissue → muscle cell → digestive system → stomach","Stomach → muscle cell → muscle tissue → digestive system","Muscle cell → stomach → digestive system → muscle tissue"],"meaning":"The diagram moves from cell to tissue to organ to system. Muscle is one of several tissue types in the stomach.","source":"Day 3 PowerPoint · slide 7"},
  {"id":"hca201a-day3-08-01","scope":"day3","topic":"Skin structure & function","term":"Integumentary system","prompt":"Which system is described on the slide as the largest and includes the skin, hair, and nails?","answer":"Integumentary","distractors":["Musculoskeletal","Lymphatic","Endocrine"],"meaning":"The slide describes the integumentary system as the largest body system. Skin itself is commonly described as the body's largest organ.","source":"Day 3 PowerPoint · slide 8","reference":{"label":"OpenStax","url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/5-1-layers-of-the-skin"}},
  {"id":"hca201a-day3-08-02","scope":"day3","topic":"Skin structure & function","term":"Layer order","prompt":"From the surface inward, what order does the skin diagram show?","answer":"Epidermis → dermis → subcutaneous tissue","distractors":["Dermis → epidermis → subcutaneous tissue","Epidermis → subcutaneous tissue → dermis","Subcutaneous tissue → epidermis → dermis"],"meaning":"The slide shows three regions. The epidermis and dermis make up the skin proper, above the subcutaneous tissue.","source":"Day 3 PowerPoint · slide 8","reference":{"label":"OpenStax","url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/5-1-layers-of-the-skin"}},
  {"id":"hca201a-day3-08-03","scope":"day3","topic":"Skin structure & function","term":"Epidermis","prompt":"Which region forms the outermost layer of the skin?","answer":"Epidermis","distractors":["Dermis","Subcutaneous fatty tissue","Superficial fascia"],"meaning":"The epidermis is the layer exposed to the environment.","source":"Day 3 PowerPoint · slide 8"},
  {"id":"hca201a-day3-08-04","scope":"day3","topic":"Skin structure & function","term":"Dermis","prompt":"Which layer sits directly below the epidermis and contains many glands and sensory endings?","answer":"Dermis","distractors":["Subcutaneous fatty tissue","Epidermis","Superficial fascia"],"meaning":"The dermis is the middle region in the three-layer diagram.","source":"Day 3 PowerPoint · slide 8"},
  {"id":"hca201a-day3-08-05","scope":"day3","topic":"Skin structure & function","term":"Subcutaneous attachment","prompt":"What role does subcutaneous fatty tissue play in the slide?","answer":"Anchors skin to structures beneath it","distractors":["Forms the main exposed barrier","Makes hair shafts above the surface","Carries sweat out through a duct opening"],"meaning":"Subcutaneous tissue helps secure the skin to deeper tissues.","source":"Day 3 PowerPoint · slide 8"},
  {"id":"hca201a-day3-08-06","scope":"day3","topic":"Skin structure & function","term":"Hair shaft","prompt":"Which part of a hair projects above the skin surface?","answer":"Hair shaft","distractors":["Hair follicle","Sebaceous gland","Sweat duct"],"meaning":"The hair shaft is the visible projecting portion of the hair.","source":"Day 3 PowerPoint · slide 8"},
  {"id":"hca201a-day3-08-07","scope":"day3","topic":"Skin structure & function","term":"Hair follicle","prompt":"Which structure surrounds the hair root and is the site of infection in a boil?","answer":"Hair follicle","distractors":["Sweat gland","Sweat duct","Sebaceous gland"],"meaning":"A follicle is a pocket in the skin that holds the developing hair.","source":"Day 3 PowerPoint · slide 8"},
  {"id":"hca201a-day3-08-08","scope":"day3","topic":"Skin structure & function","term":"Pigment layer","prompt":"Which label in the diagram refers to the part of the epidermis associated with skin colour?","answer":"Pigment layer","distractors":["Hair shaft","Sweat gland","Subcutaneous fatty tissue"],"meaning":"Melanin in the epidermis contributes to skin colour.","source":"Day 3 PowerPoint · slide 8"},
  {"id":"hca201a-day3-08-09","scope":"day3","topic":"Skin structure & function","term":"Touch receptor","prompt":"Which structure in the diagram detects touch?","answer":"Sensory nerve ending","distractors":["Sebaceous gland","Sweat duct opening","Hair shaft"],"meaning":"Skin sensory endings relay information about contact.","source":"Day 3 PowerPoint · slide 8"},
  {"id":"hca201a-day3-08-10","scope":"day3","topic":"Skin structure & function","term":"Sebaceous gland","prompt":"Which gland releases oil and is drawn next to a hair follicle?","answer":"Sebaceous gland","distractors":["Sweat gland","Adrenal gland","Salivary gland"],"meaning":"Sebaceous glands release sebum, often into a hair follicle.","source":"Day 3 PowerPoint · slide 8"},
  {"id":"hca201a-day3-08-11","scope":"day3","topic":"Skin structure & function","term":"Sweat gland","prompt":"What is the coiled structure that produces sweat in the skin diagram?","answer":"Sweat gland","distractors":["Sebaceous gland","Pigment layer","Hair follicle"],"meaning":"The sweat gland produces sweat, which then moves through its duct.","source":"Day 3 PowerPoint · slide 8"},
  {"id":"hca201a-day3-08-12","scope":"day3","topic":"Skin structure & function","term":"Sweat duct openings","prompt":"Where does sweat from a duct reach the skin surface?","answer":"At a sweat duct opening","distractors":["At the hair root","At a sensory nerve ending","At the pigment layer"],"meaning":"The diagram labels the openings at the surface of the epidermis.","source":"Day 3 PowerPoint · slide 8"},
  {"id":"hca201a-day3-09-01","scope":"day3","topic":"Skin structure & function","term":"Protective covering","prompt":"Which organ forms the body's main external protective covering?","answer":"Skin","distractors":["Spleen","Liver","Lungs"],"meaning":"Skin covers the outside of the body and is the first physical barrier against many hazards.","source":"Day 3 PowerPoint · slide 9"},
  {"id":"hca201a-day3-09-02","scope":"day3","topic":"Skin structure & function","term":"Entry barrier","prompt":"What does the intact skin barrier help keep from entering the body?","answer":"Microorganisms and other outside substances","distractors":["Water already in body tissues","Signals from skin sensory nerves","Heat from muscle activity"],"meaning":"The skin limits access to underlying tissues.","source":"Day 3 PowerPoint · slide 9"},
  {"id":"hca201a-day3-09-03","scope":"day3","topic":"Skin structure & function","term":"Water retention","prompt":"What fluid-related effect does intact skin have?","answer":"It limits excess water loss.","distractors":["It prevents water absorption by the intestines.","It filters dissolved waste from the blood.","It prevents water from reaching cells."],"meaning":"The outer barrier slows the loss of water from the body.","source":"Day 3 PowerPoint · slide 9"},
  {"id":"hca201a-day3-09-04","scope":"day3","topic":"Skin structure & function","term":"Protection from injury","prompt":"What is a protective effect of skin and underlying padding?","answer":"They shield underlying organs and tissues from injury.","distractors":["They stop joints from bending.","They maintain blood pressure without help from other systems.","They produce all of the body's protective immune cells."],"meaning":"Skin and tissue beneath it provide a protective barrier and some cushioning.","source":"Day 3 PowerPoint · slide 9"},
  {"id":"hca201a-day3-09-05","scope":"day3","topic":"Skin structure & function","term":"Skin sensation","prompt":"What can nerve endings in skin sense?","answer":"Pleasant touch as well as unpleasant stimulation","distractors":["Pain only","Temperature only","Pressure only"],"meaning":"Some receptors detect light touch and other sensations. Others detect harmful stimuli.","source":"Day 3 PowerPoint · slide 9"},
  {"id":"hca201a-day3-09-06","scope":"day3","topic":"Skin structure & function","term":"Temperature regulation","prompt":"Which response shows the skin helping regulate body temperature?","answer":"Sweat evaporates from the skin and takes heat with it.","distractors":["The kidney filters blood faster after a meal.","The stomach contracts to mix food.","The liver stores glucose as glycogen."],"meaning":"Sweat evaporation cools the body. Skin blood flow also helps control heat loss.","source":"Day 3 PowerPoint · slide 9"},
  {"id":"hca201a-day3-11-01","scope":"day3","topic":"Common skin conditions","term":"Shingles terminology","prompt":"Which term is another name for shingles?","answer":"Herpes zoster","distractors":["Varicella","Urticaria","Impetigo"],"meaning":"Herpes zoster is shingles. Varicella is chickenpox.","source":"Day 3 PowerPoint · slide 11","reference":{"label":"Public Health Agency of Canada","url":"https://www.canada.ca/en/public-health/services/infectious-diseases/fact-sheet-shingles-herpes-zoster.html"}},
  {"id":"hca201a-day3-11-02","scope":"day3","topic":"Common skin conditions","term":"Shingles and chickenpox","prompt":"Which illness is caused by the same virus as shingles?","answer":"Chickenpox","distractors":["Impetigo","Scabies","Psoriasis"],"meaning":"Varicella-zoster virus causes chickenpox and can later reactivate as shingles.","source":"Day 3 PowerPoint · slide 11","reference":{"label":"Public Health Agency of Canada","url":"https://www.canada.ca/en/public-health/services/infectious-diseases/fact-sheet-shingles-herpes-zoster.html"}},
  {"id":"hca201a-day3-11-03","scope":"day3","topic":"Common skin conditions","term":"Shingles latency","prompt":"Where does the virus remain dormant after chickenpox?","answer":"Nerve tissue","distractors":["Hair follicles","Sweat glands","The outer epidermis"],"meaning":"The virus remains inactive in nerve tissue after the original infection.","source":"Day 3 PowerPoint · slide 11","reference":{"label":"Public Health Agency of Canada","url":"https://www.canada.ca/en/public-health/services/infectious-diseases/fact-sheet-shingles-herpes-zoster.html"}},
  {"id":"hca201a-day3-11-04","scope":"day3","topic":"Common skin conditions","term":"Shingles reactivation","prompt":"Someone had chickenpox decades ago. Which explanation links that illness to shingles today?","answer":"The original virus can reactivate years later.","distractors":["The original illness turns into a bacterial infection over time.","Shingles follows only within days of chickenpox.","The virus remains active in the skin the whole time."],"meaning":"Dormancy can last years before the virus becomes active again.","source":"Day 3 PowerPoint · slide 11","reference":{"label":"Public Health Agency of Canada","url":"https://www.canada.ca/en/public-health/services/infectious-diseases/fact-sheet-shingles-herpes-zoster.html"}},
  {"id":"hca201a-day3-11-05","scope":"day3","topic":"Common skin conditions","term":"Shingles and age","prompt":"Which age-related risk factor for shingles does the slide highlight?","answer":"Being over 50","distractors":["Being between 20 and 30","Being between 10 and 20","Being under 5"],"meaning":"The risk of shingles generally increases with age. The slide highlights adults over 50.","source":"Day 3 PowerPoint · slide 11","reference":{"label":"Public Health Agency of Canada","url":"https://www.canada.ca/en/public-health/services/infectious-diseases/fact-sheet-shingles-herpes-zoster.html"}},
  {"id":"hca201a-day3-11-06","scope":"day3","topic":"Common skin conditions","term":"Shingles and infection history","prompt":"Which prior infection makes reactivation as shingles possible?","answer":"Chickenpox","distractors":["Impetigo","Strep throat","A boil"],"meaning":"After chickenpox, varicella-zoster virus can remain dormant in the body.","source":"Day 3 PowerPoint · slide 11","reference":{"label":"Public Health Agency of Canada","url":"https://www.canada.ca/en/public-health/services/infectious-diseases/fact-sheet-shingles-herpes-zoster.html"}},
  {"id":"hca201a-day3-11-07","scope":"day3","topic":"Common skin conditions","term":"Shingles and immune function","prompt":"Which immune-related change can increase a person's risk of shingles?","answer":"A weakened immune system","distractors":["An isolated change in skin colour","An increase in sweating","A healed skin abrasion"],"meaning":"People with weakened immune systems have a higher risk of shingles.","source":"Day 3 PowerPoint · slide 11","reference":{"label":"Public Health Agency of Canada","url":"https://www.canada.ca/en/public-health/services/infectious-diseases/fact-sheet-shingles-herpes-zoster.html"}},
  {"id":"hca201a-day3-11-08","scope":"day3","topic":"Common skin conditions","term":"Shingles treatment categories","prompt":"Which medication categories does the slide associate with shingles treatment?","answer":"Antivirals and pain-relief medicines","distractors":["Antibiotics and antifungals","Antihistamines and antibiotics","Antifungals and antiparasitics"],"meaning":"Antivirals target the virus. Pain-relief medicines address discomfort. A prescriber determines the treatment.","source":"Day 3 PowerPoint · slide 11","reference":{"label":"Public Health Agency of Canada","url":"https://www.canada.ca/en/public-health/services/infectious-diseases/fact-sheet-shingles-herpes-zoster.html"}},
  {"id":"hca201a-day3-11-09","scope":"day3","topic":"Common skin conditions","term":"Shingles prevention","prompt":"Which measure is intended to reduce the risk of shingles before it occurs?","answer":"Shingles vaccination","distractors":["Pain medication after a rash appears","Antivirals after symptoms start","A topical antibiotic on intact skin"],"meaning":"A shingles vaccine is available for prevention. Treatment decisions after symptoms begin are separate.","source":"Day 3 PowerPoint · slide 11","reference":{"label":"Public Health Agency of Canada","url":"https://www.canada.ca/en/public-health/services/infectious-diseases/fact-sheet-shingles-herpes-zoster.html"}},
  {"id":"hca201a-day3-12-01","scope":"day3","topic":"Common skin conditions","term":"Urticaria terminology","prompt":"What is the everyday name for urticaria?","answer":"Hives","distractors":["Shingles","Boils","Scabies"],"meaning":"Urticaria is the medical term for hives, a common skin reaction.","source":"Day 3 PowerPoint · slide 12"},
  {"id":"hca201a-day3-12-02","scope":"day3","topic":"Common skin conditions","term":"Wheals","prompt":"A client has raised, red welts after a reaction. What is the term for the individual welts?","answer":"Wheals","distractors":["Plaques","Crusts","Furuncles"],"meaning":"Hives produce raised welts called wheals.","source":"Day 3 PowerPoint · slide 12"},
  {"id":"hca201a-day3-12-03","scope":"day3","topic":"Common skin conditions","term":"Wheal size","prompt":"How does the urticaria slide describe wheal size?","answer":"It varies, and wheals can be about 5 mm or larger.","distractors":["Each wheal is exactly 5 mm wide.","Wheals are always smaller than 5 mm.","Wheals are always larger than 5 cm."],"meaning":"Wheals can vary widely in size. The 5 mm figure in the slide is an example, rather than a diagnostic cutoff.","source":"Day 3 PowerPoint · slide 12","reference":{"label":"MedlinePlus","url":"https://medlineplus.gov/ency/article/000845.htm"}},
  {"id":"hca201a-day3-12-04","scope":"day3","topic":"Common skin conditions","term":"Urticaria triggers","prompt":"What does the slide say about allergic triggers for hives?","answer":"Many different exposures can trigger them.","distractors":["They are always caused by the same type of food.","They follow only direct contact with soap.","They are caused by a bacterial infection of hair follicles."],"meaning":"Hives can be associated with many allergens and can have nonallergic causes as well.","source":"Day 3 PowerPoint · slide 12"},
  {"id":"hca201a-day3-13-01","scope":"day3","topic":"Common skin conditions","term":"Contact dermatitis","prompt":"What process defines contact dermatitis?","answer":"Skin inflammation after direct contact with an irritant or allergen","distractors":["A mite infestation in the outer skin","An infection centred on a hair follicle","A growth of abnormal pigment-producing cells"],"meaning":"Direct contact with a substance can cause either irritant or allergic contact dermatitis.","source":"Day 3 PowerPoint · slide 13"},
  {"id":"hca201a-day3-13-02","scope":"day3","topic":"Common skin conditions","term":"Irritant dermatitis triggers","prompt":"Which group contains common examples of irritants named on the slide?","answer":"Soaps, detergents, and chemicals","distractors":["Mites, yeast, and bacteria","Pollen, pet dander, and viruses","Hair shafts, sweat ducts, and follicles"],"meaning":"Soaps, detergents, and chemicals can irritate skin where they touch it.","source":"Day 3 PowerPoint · slide 13"},
  {"id":"hca201a-day3-13-03","scope":"day3","topic":"Common skin conditions","term":"Irritant dermatitis appearance","prompt":"A red patch develops where a detergent contacted the skin. How can irritant dermatitis look?","answer":"Like a burn","distractors":["Like a pus-filled lump centred on a hair","Like a closed sac with a distinct wall","Like narrow mite burrows between the fingers"],"meaning":"An irritant reaction can resemble a burn and is linked to the area of exposure.","source":"Day 3 PowerPoint · slide 13"},
  {"id":"hca201a-day3-14-01","scope":"day3","topic":"Common skin conditions","term":"Eczema inflammation","prompt":"How does the slide classify eczema?","answer":"An inflammatory skin condition","distractors":["A contagious bacterial infection","A viral reactivation","A mite infestation"],"meaning":"Eczema involves skin inflammation.","source":"Day 3 PowerPoint · slide 14"},
  {"id":"hca201a-day3-14-02","scope":"day3","topic":"Common skin conditions","term":"Eczema variation","prompt":"How consistent is eczema's appearance across clients?","answer":"The appearance can differ from person to person.","distractors":["It always appears as a single red ring.","It always begins with identical pus-filled lumps.","It always forms the same pattern of raised wheals."],"meaning":"Location, colour, and appearance can vary. One example image cannot represent every presentation.","source":"Day 3 PowerPoint · slide 14"},
  {"id":"hca201a-day3-14-03","scope":"day3","topic":"Common skin conditions","term":"Eczema features","prompt":"Which combination best matches the usual eczema description on the slide?","answer":"Dry, inflamed, very itchy patches","distractors":["Tender lumps containing pus","Raised welts that come and go","A closed sac filled with fluid"],"meaning":"The slide describes dry, red, intensely itchy patches. Inflammation can look different across skin tones.","source":"Day 3 PowerPoint · slide 14"},
  {"id":"hca201a-day3-15-01","scope":"day3","topic":"Common skin conditions","term":"Scabies cause and contagiousness","prompt":"Which description fits scabies?","answer":"A highly contagious infestation caused by a mite","distractors":["An inflammatory disorder caused by an irritant","An infection of a hair follicle caused by bacteria","A viral reactivation in nerve tissue"],"meaning":"Scabies is a skin infestation with human itch mites and can spread between people.","source":"Day 3 PowerPoint · slide 15"},
  {"id":"hca201a-day3-15-02","scope":"day3","topic":"Common skin conditions","term":"Scabies itch","prompt":"What accounts for intense itching in scabies?","answer":"The skin reacts to mites and their eggs after the mites burrow.","distractors":["A dormant virus travels down a nerve.","Bacteria multiply in a single infected follicle.","Skin cells collect in raised, scaly plaques."],"meaning":"The mites burrow into superficial skin and lay eggs. The body's reaction triggers itching.","source":"Day 3 PowerPoint · slide 15"},
  {"id":"hca201a-day3-15-03","scope":"day3","topic":"Common skin conditions","term":"Scabies transmission","prompt":"Which exposure commonly spreads scabies?","answer":"Prolonged direct skin-to-skin contact","distractors":["Breathing the same air across a room","Drinking from the same water source","Briefly speaking to someone by phone"],"meaning":"Close skin contact is the main route. See CDC guidance on scabies spread.","source":"Day 3 PowerPoint · slide 15","reference":{"label":"CDC","url":"https://www.cdc.gov/scabies/causes/"}},
  {"id":"hca201a-day3-15-04","scope":"day3","topic":"Common skin conditions","term":"Scabies before diagnosis","prompt":"Can someone spread scabies before they have obvious symptoms or a diagnosis?","answer":"Yes, they may spread it for weeks before symptoms appear.","distractors":["Only after a visible rash appears.","Only during the first day of treatment.","Only after diagnosis has been confirmed."],"meaning":"CDC notes that with a first infestation symptoms can take 4–8 weeks to appear, and spread is possible during that time.","source":"Day 3 PowerPoint · slide 15","reference":{"label":"CDC","url":"https://www.cdc.gov/scabies/about/"}},
  {"id":"hca201a-day3-16-01","scope":"day3","topic":"Common skin conditions","term":"Psoriasis appearance and course","prompt":"Which description best fits the psoriasis pattern taught in the slide?","answer":"A chronic condition with inflamed, scaly plaques","distractors":["An acute bacterial infection with a draining crust","A short-lived reaction with raised wheals","A closed sac surrounded by a membrane"],"meaning":"Psoriasis is a chronic inflammatory skin condition. Its thicker, scaly areas are called plaques.","source":"Day 3 PowerPoint · slide 16"},
  {"id":"hca201a-day3-16-02","scope":"day3","topic":"Common skin conditions","term":"Psoriasis location","prompt":"What does the slide say about where psoriasis plaques can occur?","answer":"They can occur anywhere on the body.","distractors":["They are restricted to the scalp.","They occur only around infected follicles.","They occur only on the palms and soles."],"meaning":"Some locations are common, but plaques can occur on many parts of the body.","source":"Day 3 PowerPoint · slide 16"},
  {"id":"hca201a-day3-16-03","scope":"day3","topic":"Common skin conditions","term":"Psoriasis plaque formation","prompt":"What builds up in a psoriasis plaque?","answer":"Skin cells accumulating faster than they are shed","distractors":["Pus collecting around a hair follicle","Fluid collecting inside a cyst wall","Mites and eggs filling a sweat duct"],"meaning":"Rapid skin-cell turnover contributes to thick, inflamed, scaly patches.","source":"Day 3 PowerPoint · slide 16"},
  {"id":"hca201a-day3-16-04","scope":"day3","topic":"Common skin conditions","term":"Psoriasis cause","prompt":"How should the slide's statement about the cause of psoriasis be understood?","answer":"Its exact cause is unclear, with immune and genetic factors involved.","distractors":["It is caused by an identified mite.","It comes from a single bacterial species.","It follows direct exposure to detergents in every case."],"meaning":"Psoriasis involves immune activity and genetic susceptibility, with triggers that can vary between people.","source":"Day 3 PowerPoint · slide 16","reference":{"label":"NIAMS","url":"https://www.niams.nih.gov/health-topics/psoriasis"}},
  {"id":"hca201a-day3-17-01","scope":"day3","topic":"Common skin conditions","term":"Boil terminology","prompt":"What is another name for a boil?","answer":"Furuncle","distractors":["Wheal","Plaque","Ganglion"],"meaning":"Furuncle is the medical term for a boil.","source":"Day 3 PowerPoint · slide 17"},
  {"id":"hca201a-day3-17-02","scope":"day3","topic":"Common skin conditions","term":"Boil cause","prompt":"Which combination describes the usual source of a boil?","answer":"Staphylococcus infection of a hair follicle","distractors":["Streptococcus infection of a sweat duct","Varicella-zoster virus in an oil gland","A mite burrowing into a nerve ending"],"meaning":"A boil forms when a hair follicle becomes infected, commonly with Staphylococcus.","source":"Day 3 PowerPoint · slide 17"},
  {"id":"hca201a-day3-17-03","scope":"day3","topic":"Common skin conditions","term":"Boil appearance","prompt":"Which description best fits a boil?","answer":"A red, painful, pus-filled lump","distractors":["A dry, scaly, inflamed plaque","A cluster of raised welts","A closed, usually painless fluid-filled sac near a joint"],"meaning":"A boil is an inflamed, tender lump with pus.","source":"Day 3 PowerPoint · slide 17"},
  {"id":"hca201a-day3-17-04","scope":"day3","topic":"Common skin conditions","term":"Boil sites","prompt":"Which group lists the common boil sites from the slide?","answer":"Back, underarms, shoulders, thighs, and buttocks","distractors":["Palms, soles, and nails","Lips, tongue, and gums","Eyelids, nostrils, and ear canals"],"meaning":"The slide lists the back, armpits, shoulders, thighs, and buttocks as common sites.","source":"Day 3 PowerPoint · slide 17"},
  {"id":"hca201a-day3-18-01","scope":"day3","topic":"Common skin conditions","term":"Cyst definition and location","prompt":"What is a cyst as defined by the slide?","answer":"An abnormal closed sac that can form in different parts of the body","distractors":["A visible patch of thickened skin with no enclosed space","An infected hair follicle filled with pus","A cluster of raised welts after an allergic reaction"],"meaning":"A cyst is a closed sac. Its location depends on the type of cyst.","source":"Day 3 PowerPoint · slide 18"},
  {"id":"hca201a-day3-18-02","scope":"day3","topic":"Common skin conditions","term":"Cyst contents","prompt":"What can a cyst contain?","answer":"Air, fluid, or semi-solid material","distractors":["Only blood","Only pus","Only solid bone"],"meaning":"The contents vary with the cyst type.","source":"Day 3 PowerPoint · slide 18"},
  {"id":"hca201a-day3-18-03","scope":"day3","topic":"Common skin conditions","term":"Cyst wall","prompt":"What encloses the contents of a cyst?","answer":"A distinct membrane or wall","distractors":["A hair shaft","A sweat duct","A skin nerve ending"],"meaning":"The enclosing wall gives the sac a distinct boundary.","source":"Day 3 PowerPoint · slide 18"},
  {"id":"hca201a-day3-18-04","scope":"day3","topic":"Common skin conditions","term":"Cyst persistence and treatment","prompt":"Which statement best describes whether cysts persist or need removal?","answer":"It depends on the type. Some persist, while others can resolve on their own.","distractors":["Every cyst needs surgery to resolve.","Every cyst disappears within a few days.","Medication is necessary for every cyst."],"meaning":"The slide emphasizes persistence and treatment. Some cysts, including some ganglion cysts, may resolve without treatment.","source":"Day 3 PowerPoint · slide 18","reference":{"label":"NHS","url":"https://www.nhs.uk/conditions/ganglion-cyst/"}},
  {"id":"hca201a-day3-18-05","scope":"day3","topic":"Common skin conditions","term":"Ganglion cyst","prompt":"Which cyst type is labelled in the hand illustration?","answer":"Ganglion cyst","distractors":["Epidermoid cyst","Pilonidal cyst","Ovarian cyst"],"meaning":"The diagram labels a ganglion cyst in the hand. These commonly occur near hand or wrist joints.","source":"Day 3 PowerPoint · slide 18"},
  {"id":"hca201a-day3-19-01","scope":"day3","topic":"Common skin conditions","term":"Impetigo cause","prompt":"Which organisms can cause contagious impetigo?","answer":"Streptococcus or Staphylococcus bacteria","distractors":["Varicella-zoster viruses","Human itch mites","Dermatophyte fungi"],"meaning":"Impetigo is bacterial and can be caused by strep or staph.","source":"Day 3 PowerPoint · slide 19"},
  {"id":"hca201a-day3-19-02","scope":"day3","topic":"Common skin conditions","term":"Skin breaks and impetigo","prompt":"Which skin change can provide an entry point for impetigo bacteria?","answer":"A cut or scratch","distractors":["A healed scar with intact skin","Normal sweating after exercise","A mole that has never changed"],"meaning":"A break in the skin can become infected.","source":"Day 3 PowerPoint · slide 19"},
  {"id":"hca201a-day3-19-03","scope":"day3","topic":"Common skin conditions","term":"Self-spread of impetigo","prompt":"Which action can transfer impetigo bacteria to another part of the same person's body?","answer":"Scratching an infected patch and touching nearby skin","distractors":["Moving the joint under the lesion","Looking at the patch in a mirror","Lightly touching intact skin without contacting the lesion"],"meaning":"Hands can transfer bacteria from a lesion to another area after scratching.","source":"Day 3 PowerPoint · slide 19"},
  {"id":"hca201a-day3-19-04","scope":"day3","topic":"Common skin conditions","term":"Impetigo crust and drainage","prompt":"What feature of impetigo lesions can help the infection spread?","answer":"Sores can drain before or as a crust forms.","distractors":["A deep membrane keeps all contents sealed.","Scaly plaques remain dry and intact.","A closed follicle holds the lesion below the surface."],"meaning":"Impetigo sores can ooze and then crust. Contact with drainage can spread bacteria.","source":"Day 3 PowerPoint · slide 19"},
  {"id":"hca201a-day3-20-01","scope":"day3","topic":"Cancer, risk & detection","term":"Normal cell reproduction","prompt":"Why do cells normally reproduce?","answer":"To support tissue growth and repair","distractors":["To allow malignant cells to spread","To form a tumour whenever an organ grows","To replace every organ on a fixed schedule"],"meaning":"Controlled cell division allows tissues to grow and replace damaged or worn-out cells.","source":"Day 3 PowerPoint · slide 20"},
  {"id":"hca201a-day3-20-02","scope":"day3","topic":"Cancer, risk & detection","term":"Uncontrolled division","prompt":"What has changed when abnormal cells keep dividing despite normal growth controls?","answer":"Cell division and growth have become uncontrolled.","distractors":["Cell division has stopped throughout the body.","Normal cells are repairing a small injury.","The body has achieved homeostasis."],"meaning":"Loss of normal growth control is a defining feature of cancer.","source":"Day 3 PowerPoint · slide 20"},
  {"id":"hca201a-day3-20-03","scope":"day3","topic":"Cancer, risk & detection","term":"Tumour definition","prompt":"What is a mass that forms from abnormal cell growth called?","answer":"Tumour","distractors":["Metastasis","Cyst wall","Plaque"],"meaning":"A tumour is a mass of abnormal tissue. Tumours can be benign or malignant, and some cancers do not form a solid tumour.","source":"Day 3 PowerPoint · slide 20"},
  {"id":"hca201a-day3-20-04","scope":"day3","topic":"Cancer, risk & detection","term":"Benign meaning","prompt":"A report calls a tumour benign. What does that mean?","answer":"It is noncancerous.","distractors":["It has already spread to a distant site.","It must be an early stage of cancer.","It is made up exclusively of fluid."],"meaning":"Benign tumours are noncancerous and do not metastasize.","source":"Day 3 PowerPoint · slide 20"},
  {"id":"hca201a-day3-20-05","scope":"day3","topic":"Cancer, risk & detection","term":"Malignant meaning","prompt":"What does it mean when a tumour is described as malignant?","answer":"It is cancerous.","distractors":["It is a noncancerous growth.","It is normal tissue repairing itself.","It is always a fluid-filled sac."],"meaning":"Malignant tumours are cancerous and can invade nearby tissue.","source":"Day 3 PowerPoint · slide 20"},
  {"id":"hca201a-day3-21-01","scope":"day3","topic":"Cancer, risk & detection","term":"Local invasion","prompt":"What can a malignant tumour do to nearby tissue?","answer":"Invade and destroy it","distractors":["Turn the nearby tissue into a benign growth","Replace only damaged cells during normal repair","Remain separated from nearby tissue in every case"],"meaning":"Malignant cells can grow into surrounding tissues and damage them.","source":"Day 3 PowerPoint · slide 21"},
  {"id":"hca201a-day3-21-02","scope":"day3","topic":"Cancer, risk & detection","term":"Distant spread","prompt":"Which tumour type can spread to distant body parts?","answer":"Malignant tumour","distractors":["Benign tumour","Simple cyst","Noncancerous skin plaque"],"meaning":"The ability to spread to a distant site is a feature of cancer.","source":"Day 3 PowerPoint · slide 21"},
  {"id":"hca201a-day3-21-03","scope":"day3","topic":"Cancer, risk & detection","term":"Life-threatening cancer","prompt":"What does the slide say about the seriousness of a malignant tumour?","answer":"It can be life-threatening.","distractors":["It is harmless if it looks small.","It is harmless unless it appears on the skin.","It always resolves by itself."],"meaning":"Malignant disease can threaten life through local damage or spread, among other effects.","source":"Day 3 PowerPoint · slide 21"},
  {"id":"hca201a-day3-21-04","scope":"day3","topic":"Cancer, risk & detection","term":"Malignant recurrence","prompt":"What does recurrence after removal mean?","answer":"A malignant tumour has grown back after treatment.","distractors":["The original mass is confirmed to be benign.","Normal tissue has completed wound healing.","The diagnosis has changed from malignant to noncancerous."],"meaning":"Some malignancies recur even after the original tumour has been removed.","source":"Day 3 PowerPoint · slide 21"},
  {"id":"hca201a-day3-21-05","scope":"day3","topic":"Cancer, risk & detection","term":"Benign and metastasis","prompt":"Which feature separates a benign tumour from a malignant tumour that has metastasized?","answer":"A benign tumour does not spread to distant sites.","distractors":["A benign tumour cannot grow beyond a few millimetres.","A benign tumour always causes more pain.","A benign tumour has already produced distant tumours."],"meaning":"Benign tumours can grow locally but do not metastasize.","source":"Day 3 PowerPoint · slide 21"},
  {"id":"hca201a-day3-21-06","scope":"day3","topic":"Cancer, risk & detection","term":"Benign size and seriousness","prompt":"Can a benign tumour become large and still be noncancerous?","answer":"Yes. It can grow large and rarely threatens life, although location can matter.","distractors":["No. Size alone determines malignancy.","No. A benign tumour always shrinks once noticed.","Yes. Large benign tumours routinely spread to other organs."],"meaning":"Size alone does not establish cancer. A benign tumour can still cause harm if it presses on an important structure.","source":"Day 3 PowerPoint · slide 21"},
  {"id":"hca201a-day3-21-07","scope":"day3","topic":"Cancer, risk & detection","term":"Benign recurrence","prompt":"According to the slide, what usually happens after a benign tumour is removed?","answer":"It usually does not grow back.","distractors":["It usually spreads to distant locations.","It always becomes malignant.","It usually forms a new tumour elsewhere."],"meaning":"Benign tumours usually do not recur after removal, although some can recur.","source":"Day 3 PowerPoint · slide 21"},
  {"id":"hca201a-day3-22-01","scope":"day3","topic":"Cancer, risk & detection","term":"Metastasis definition","prompt":"What term means the spread of cancer to another part of the body?","answer":"Metastasis","distractors":["Homeostasis","Local inflammation","Tissue repair"],"meaning":"Metastasis is cancer spread away from its original site.","source":"Day 3 PowerPoint · slide 22"},
  {"id":"hca201a-day3-22-02","scope":"day3","topic":"Cancer, risk & detection","term":"Metastatic cell travel","prompt":"What can happen before a distant tumour forms?","answer":"Cancer cells break away from the original tumour and travel.","distractors":["Normal cells from the distant site travel to the original tumour.","The original mass moves intact to a different organ.","The original tumour first changes into a benign cyst."],"meaning":"Cancer cells can travel through blood or lymph after breaking away from the primary tumour.","source":"Day 3 PowerPoint · slide 22"},
  {"id":"hca201a-day3-22-03","scope":"day3","topic":"Cancer, risk & detection","term":"Secondary tumour growth","prompt":"What happens if cells that travelled from a primary tumour grow at a new site?","answer":"A metastatic tumour can form there.","distractors":["The original cancer automatically becomes benign.","Normal tissue repair prevents any new growth.","Only a cyst can form at the new site."],"meaning":"A metastatic tumour is made of cells from the original cancer even when it is in a different organ.","source":"Day 3 PowerPoint · slide 22"},
  {"id":"hca201a-day3-22-04","scope":"day3","topic":"Cancer, risk & detection","term":"Where cancer occurs","prompt":"How limited is cancer to a particular part of the body?","answer":"It can start almost anywhere in the body.","distractors":["It can start only in the skin.","It can start only in the digestive system.","It can start only in organs inside the thorax."],"meaning":"Many different cell types and tissues can give rise to cancer.","source":"Day 3 PowerPoint · slide 22"},
  {"id":"hca201a-day3-22-05","scope":"day3","topic":"Cancer, risk & detection","term":"Leading cause of death in Canada","prompt":"How does the Canadian Cancer Society currently rank cancer as a cause of death in Canada?","answer":"It is the leading cause.","distractors":["It is the second leading cause.","It is the third leading cause.","It is outside the five leading causes."],"meaning":"The slide says second. The Canadian Cancer Society's 2026 overview identifies cancer as Canada's leading cause of death.","source":"Day 3 PowerPoint · slide 22","reference":{"label":"Canadian Cancer Society","url":"https://cancer.ca/en/about-us/stories/2026/5-things-to-know-about-cancer-in-canada-in-2026"}},
  {"id":"hca201a-day3-23-01","scope":"day3","topic":"Cancer, risk & detection","term":"Malignant melanoma","prompt":"Which skin cancer does the slide single out as particularly dangerous?","answer":"Melanoma","distractors":["Basal cell carcinoma","Squamous cell carcinoma","Actinic keratosis"],"meaning":"Melanoma can spread and can be fatal. Early detection and treatment matter.","source":"Day 3 PowerPoint · slide 23"},
  {"id":"hca201a-day3-23-02","scope":"day3","topic":"Cancer, risk & detection","term":"Early melanoma care","prompt":"Why does the slide emphasize treating melanoma early?","answer":"It can become life-threatening if it grows and spreads.","distractors":["It becomes harmless once it spreads.","Early care matters only for appearance.","Its risk is determined solely by the size of the visible mole."],"meaning":"Early treatment can address melanoma before it spreads to other parts of the body.","source":"Day 3 PowerPoint · slide 23","reference":{"label":"Canadian Cancer Society","url":"https://cancer.ca/en/cancer-information/cancer-types/melanoma-skin/signs-and-symptoms"}},
  {"id":"hca201a-day3-24-01","scope":"day3","topic":"Cancer, risk & detection","term":"Cancer causes and risks","prompt":"How should a list of cancer risk factors be interpreted?","answer":"Cancer can arise from a mix of factors, and the exact cause in one person may be unclear.","distractors":["Every case of cancer has the same identifiable cause.","One risk factor always proves what caused a person's cancer.","Cancer can occur only in people with a known risk factor."],"meaning":"A risk factor raises the likelihood of cancer. It cannot by itself tell us why an individual developed it.","source":"Day 3 PowerPoint · slide 24"},
  {"id":"hca201a-day3-24-02","scope":"day3","topic":"Cancer, risk & detection","term":"Family history","prompt":"Which item on the slide is a family or inherited risk clue?","answer":"A family history of cancer","distractors":["Smoking tobacco","Drinking alcohol","Regular exposure to UV radiation"],"meaning":"Family history can indicate inherited susceptibility or exposures shared by relatives.","source":"Day 3 PowerPoint · slide 24"},
  {"id":"hca201a-day3-24-03","scope":"day3","topic":"Cancer, risk & detection","term":"Tobacco and cancer","prompt":"Which behaviour on the slide directly exposes a person to carcinogens in tobacco smoke?","answer":"Smoking","distractors":["Drinking alcohol","Eating a low-fibre diet","Limiting sun exposure"],"meaning":"Smoking is a major preventable cancer risk.","source":"Day 3 PowerPoint · slide 24"},
  {"id":"hca201a-day3-24-04","scope":"day3","topic":"Cancer, risk & detection","term":"Alcohol and cancer","prompt":"Which statement describes the alcohol risk factor on the slide?","answer":"Drinking alcohol can increase the risk of some cancers.","distractors":["Alcohol is protective if consumed with meals.","Only cigarette smoking can affect cancer risk.","Alcohol affects risk only when a family history is present."],"meaning":"The slide calls out heavy use. Cancer risk can rise with alcohol intake even below levels typically described as heavy.","source":"Day 3 PowerPoint · slide 24"},
  {"id":"hca201a-day3-24-05","scope":"day3","topic":"Cancer, risk & detection","term":"Diet and cancer risk","prompt":"Which eating pattern is flagged on the slide?","answer":"High-fat, high-calorie, and low in fibre","distractors":["Fibre-rich with a variety of plant foods","Rich in whole grains and legumes","Balanced with plenty of vegetables and fruit"],"meaning":"The slide points to an overall dietary pattern. Diet, body weight, and other factors can affect risk for particular cancers.","source":"Day 3 PowerPoint · slide 24"},
  {"id":"hca201a-day3-24-06","scope":"day3","topic":"Cancer, risk & detection","term":"Radiation and cancer risk","prompt":"Which everyday example illustrates the radiation risk on the slide?","answer":"Ultraviolet radiation from the sun","distractors":["Ordinary room sound","Heat from a warm drink","Air pressure from a fan"],"meaning":"UV radiation from sunlight can damage skin cells and raise skin cancer risk.","source":"Day 3 PowerPoint · slide 24"},
  {"id":"hca201a-day3-24-07","scope":"day3","topic":"Cancer, risk & detection","term":"Chemical carcinogens","prompt":"What do we call certain substances that can cause cancer?","answer":"Carcinogens","distractors":["Antibodies","Antivirals","Analgesics"],"meaning":"Some chemical exposures increase cancer risk. Such agents are called carcinogens.","source":"Day 3 PowerPoint · slide 24"},
  {"id":"hca201a-day3-24-08","scope":"day3","topic":"Cancer, risk & detection","term":"Hormones and cancer risk","prompt":"Which internal biological factor appears in the slide's cancer risk list?","answer":"Hormones","distractors":["Epithelial tissue type by itself","Pain from a previous injury","A healed scar by itself"],"meaning":"Hormonal exposure can influence risk for some cancers. The effect depends on the hormone and cancer type.","source":"Day 3 PowerPoint · slide 24"},
  {"id":"hca201a-day3-24-09","scope":"day3","topic":"Cancer, risk & detection","term":"Viruses and cancer risk","prompt":"Which infectious agents are listed as potential risk factors for some cancers?","answer":"Certain viruses","distractors":["The mites that cause scabies","The bacteria that cause a typical boil","All infectious agents equally"],"meaning":"Some viruses, such as HPV, can raise the risk of particular cancers. Risk varies by virus and infection.","source":"Day 3 PowerPoint · slide 24"},
  {"id":"hca201a-day3-25-01","scope":"day3","topic":"Cancer, risk & detection","term":"Early detection","prompt":"Why does the Canadian Cancer Society emphasize early detection?","answer":"Finding cancer sooner can improve treatment options and outcomes.","distractors":["Finding cancer removes the need for treatment.","Cancer can be detected early only after it spreads.","Early detection guarantees that cancer cannot recur."],"meaning":"Early detection helps find cancer sooner. Prevention aims to lower the chance of cancer developing in the first place.","source":"Day 3 PowerPoint · slide 25"},
  {"id":"hca201a-day3-25-02","scope":"day3","topic":"Cancer, risk & detection","term":"ABCDE asymmetry","prompt":"What does the A in the mole comparison stand for?","answer":"Asymmetry","distractors":["Area","Age","Attachment"],"meaning":"Asymmetry means one half looks different from the other. The slide compares symmetrical and asymmetrical examples.","source":"Day 3 PowerPoint · slide 25","reference":{"label":"Canadian Cancer Society","url":"https://cancer.ca/en/cancer-information/cancer-types/melanoma-skin/signs-and-symptoms"}},
  {"id":"hca201a-day3-25-03","scope":"day3","topic":"Cancer, risk & detection","term":"ABCDE border","prompt":"Which border finding is a warning feature in the slide's mole comparison?","answer":"An uneven or irregular border","distractors":["A smooth, even border","A clearly circular, uniform border","A stable, sharp border all the way around"],"meaning":"B stands for border. Irregular edges are one reason a mole may need assessment.","source":"Day 3 PowerPoint · slide 25","reference":{"label":"Canadian Cancer Society","url":"https://cancer.ca/en/cancer-information/cancer-types/melanoma-skin/signs-and-symptoms"}},
  {"id":"hca201a-day3-25-04","scope":"day3","topic":"Cancer, risk & detection","term":"ABCDE colour","prompt":"Which colour pattern is flagged in the slide's examples?","answer":"Multiple colours in one spot","distractors":["One even colour across the spot","A single uniform shade with no change","A spot matching its previous colour exactly"],"meaning":"C stands for colour. Uneven colour or several colours in one lesion may be a warning sign.","source":"Day 3 PowerPoint · slide 25","reference":{"label":"Canadian Cancer Society","url":"https://cancer.ca/en/cancer-information/cancer-types/melanoma-skin/signs-and-symptoms"}},
  {"id":"hca201a-day3-25-05","scope":"day3","topic":"Cancer, risk & detection","term":"ABCDE diameter","prompt":"What size does the slide use as a diameter clue, while still allowing for smaller melanomas?","answer":"About ¼ inch (6 mm)","distractors":["About 1 mm","About ½ inch (13 mm)","About 1 inch (25 mm)"],"meaning":"D stands for diameter. A spot around 6 mm or larger can be suspicious, and smaller melanomas can also occur.","source":"Day 3 PowerPoint · slide 25","reference":{"label":"Canadian Cancer Society","url":"https://cancer.ca/en/cancer-information/cancer-types/melanoma-skin/signs-and-symptoms"}},
  {"id":"hca201a-day3-25-06","scope":"day3","topic":"Cancer, risk & detection","term":"ABCDE evolution","prompt":"What does evolution mean when checking a mole?","answer":"It changes in size, shape, or colour over time.","distractors":["It remains stable in size, shape, and colour.","It is medium-sized on one check.","It is symmetrical on one check."],"meaning":"E stands for evolving. A new or changing skin spot may need assessment.","source":"Day 3 PowerPoint · slide 25","reference":{"label":"Canadian Cancer Society","url":"https://cancer.ca/en/cancer-information/cancer-types/melanoma-skin/signs-and-symptoms"}},
  {"id":"hca201a-day3-26-01","scope":"day3","topic":"Cancer treatment","term":"Early treatment","prompt":"What can early detection make possible in cancer care?","answer":"Treatment and control before the disease becomes more advanced","distractors":["A guarantee that no further care is needed","Using the same treatment for all tumour types","Skipping all assessment of tumour spread"],"meaning":"Finding cancer earlier may improve the chance of effective treatment or control.","source":"Day 3 PowerPoint · slide 26"},
  {"id":"hca201a-day3-26-02","scope":"day3","topic":"Cancer treatment","term":"Tumour type","prompt":"Why does the care team need to know the type of tumour when planning treatment?","answer":"Different tumour types can respond to different treatments.","distractors":["Tumour type determines only the appointment time.","All tumour types respond to the same therapy.","Tumour type matters only once a tumour is removed."],"meaning":"The type of tumour is one of the main factors in selecting treatment.","source":"Day 3 PowerPoint · slide 26"},
  {"id":"hca201a-day3-26-03","scope":"day3","topic":"Cancer treatment","term":"Tumour site","prompt":"What does tumour site tell the care team?","answer":"Where the tumour is located","distractors":["Whether the tumour has come back","How fast a person's pulse is","How long symptoms have been present"],"meaning":"Location affects which treatment approaches can be used.","source":"Day 3 PowerPoint · slide 26"},
  {"id":"hca201a-day3-26-04","scope":"day3","topic":"Cancer treatment","term":"Tumour size","prompt":"Which measurement is a factor in deciding how to treat a tumour?","answer":"Its size","distractors":["The colour of the client's hair","The client's shoe size","The number of visitors the client receives"],"meaning":"The size of a tumour can influence which treatment is appropriate.","source":"Day 3 PowerPoint · slide 26"},
  {"id":"hca201a-day3-26-05","scope":"day3","topic":"Cancer treatment","term":"Tumour spread","prompt":"What question about spread helps determine treatment?","answer":"Has the tumour spread beyond the original site?","distractors":["Did the client notice the lump before breakfast?","Does the client remember the day the tumour started growing?","Did two clients receive their diagnoses in the same month?"],"meaning":"Cancer spread is one factor in staging and in choosing treatment.","source":"Day 3 PowerPoint · slide 26"},
  {"id":"hca201a-day3-26-06","scope":"day3","topic":"Cancer treatment","term":"Cure as a goal","prompt":"Which treatment goal aims to eliminate the cancer?","answer":"Cure","distractors":["Disease control","Symptom relief","Early detection"],"meaning":"Cure aims to eliminate the cancer. The team may choose other goals when appropriate.","source":"Day 3 PowerPoint · slide 26"},
  {"id":"hca201a-day3-26-07","scope":"day3","topic":"Cancer treatment","term":"Control as a goal","prompt":"A treatment aims to slow cancer growth over time. Which goal is this?","answer":"Control the disease","distractors":["Detect the cancer for the first time","Identify a risk factor","Prevent every treatment side effect"],"meaning":"Disease control aims to slow or limit progression.","source":"Day 3 PowerPoint · slide 26"},
  {"id":"hca201a-day3-26-08","scope":"day3","topic":"Cancer treatment","term":"Symptom relief as a goal","prompt":"Which goal best fits treatment intended to reduce symptoms for as long as possible?","answer":"Symptom relief","distractors":["Cure","Screening","Assessing family history"],"meaning":"Reducing symptoms can improve comfort and quality of life.","source":"Day 3 PowerPoint · slide 26"},
  {"id":"hca201a-day3-26-09","scope":"day3","topic":"Cancer treatment","term":"Single or combined treatment","prompt":"How many types of treatment may be appropriate for cancer?","answer":"One may be enough, or a combination may work best.","distractors":["Every cancer responds best to one type only.","Every cancer requires at least three types.","Combining treatments is only used after remission."],"meaning":"Different cancers call for different plans. Some respond best to one therapy and others to several.","source":"Day 3 PowerPoint · slide 26"},
  {"id":"hca201a-day3-27-01","scope":"day3","topic":"Cancer treatment","term":"Treatment side effects","prompt":"Which treatment details influence the side effects a client may experience?","answer":"The type and extent of the treatment","distractors":["Only the original location of the cancer","Only the day treatment starts","Only whether treatment is delivered near home"],"meaning":"Side effects vary with the type and extent of treatment and with individual circumstances.","source":"Day 3 PowerPoint · slide 27"},
  {"id":"hca201a-day3-27-02","scope":"day3","topic":"Cancer treatment","term":"Surgical removal","prompt":"Which treatment physically removes a tumour?","answer":"Surgery","distractors":["Radiation therapy","Chemotherapy","Immunotherapy"],"meaning":"Surgery removes tissue from the body. Other methods act on the tumour or cancer cells in other ways.","source":"Day 3 PowerPoint · slide 27"},
  {"id":"hca201a-day3-27-03","scope":"day3","topic":"Cancer treatment","term":"Surgical cure or control","prompt":"Which cancer treatment goals can surgery serve by removing tumour tissue?","answer":"Cure or disease control","distractors":["Screening and primary prevention only","Changing inherited risk","Identifying every treatment side effect"],"meaning":"Depending on the case, removing cancer surgically may aim at cure or control.","source":"Day 3 PowerPoint · slide 27"},
  {"id":"hca201a-day3-27-04","scope":"day3","topic":"Cancer treatment","term":"Surgery and advanced cancer pain","prompt":"Why might a surgical team remove part of a tumour in advanced cancer when cure is unlikely?","answer":"To reduce pain or pressure caused by the tumour","distractors":["To cause the cancer to spread more slowly by relieving worry alone","To screen an otherwise healthy population","To estimate inherited cancer risk"],"meaning":"Reducing the tumour's pressure on nearby structures may relieve pain.","source":"Day 3 PowerPoint · slide 27"},
  {"id":"hca201a-day3-27-05","scope":"day3","topic":"Cancer treatment","term":"Radiation tumour destruction","prompt":"Which treatment uses targeted radiation to destroy certain tumours?","answer":"Radiotherapy","distractors":["Surgical removal","Hormone therapy","Immunotherapy"],"meaning":"Radiotherapy uses radiation to damage cancer cells in the area treated.","source":"Day 3 PowerPoint · slide 27"},
  {"id":"hca201a-day3-27-06","scope":"day3","topic":"Cancer treatment","term":"Preoperative radiation","prompt":"Why might radiotherapy be given before a tumour operation?","answer":"To shrink the tumour before removal","distractors":["To replace wound healing after the operation","To remove tissue with surgical instruments","To block production of a hormone throughout the body"],"meaning":"Shrinkage can make a tumour easier to remove.","source":"Day 3 PowerPoint · slide 27"},
  {"id":"hca201a-day3-27-07","scope":"day3","topic":"Cancer treatment","term":"Postoperative radiation","prompt":"Why might radiotherapy be aimed at the area where a tumour was removed?","answer":"To destroy cancer cells that may remain in that area","distractors":["To increase the growth of any remaining cancer cells","To re-create tissue removed at surgery","To detect the original tumour before surgery"],"meaning":"Postoperative radiotherapy can target residual cells near the surgical site.","source":"Day 3 PowerPoint · slide 27"},
  {"id":"hca201a-day3-27-08","scope":"day3","topic":"Cancer treatment","term":"Radiation and pain","prompt":"What can radiation do for pain related to tumour growth?","answer":"Control tumour growth to prevent or relieve pain","distractors":["Act only as a sedative during treatment","Remove all pain instantly in every case","Prevent discomfort solely by stimulating appetite"],"meaning":"By reducing or controlling a tumour, radiation may help with pain.","source":"Day 3 PowerPoint · slide 27"},
  {"id":"hca201a-day3-28-01","scope":"day3","topic":"Cancer treatment","term":"Chemotherapy mechanism","prompt":"Which treatment uses drugs that kill fast-growing cells, including cancer cells?","answer":"Chemotherapy","distractors":["Radiotherapy","Surgery","Hormone therapy"],"meaning":"Chemotherapy uses drugs. Some healthy fast-growing cells can also be affected.","source":"Day 3 PowerPoint · slide 28"},
  {"id":"hca201a-day3-28-02","scope":"day3","topic":"Cancer treatment","term":"Preoperative chemotherapy","prompt":"Why might chemotherapy be given before an operation?","answer":"To shrink a tumour before surgery","distractors":["To inspect the margins after the operation","To remove an organ with instruments","To use radiation on a single treatment field"],"meaning":"Preoperative chemotherapy can shrink a tumour and may make surgery easier.","source":"Day 3 PowerPoint · slide 28"},
  {"id":"hca201a-day3-28-03","scope":"day3","topic":"Cancer treatment","term":"Chemotherapy and dispersed cells","prompt":"Why can chemotherapy be useful when some cells may have left the main tumour?","answer":"It can reach and act on cancer cells away from the main tumour.","distractors":["It acts only where a surgical cut is made.","It works by physically removing each distant cell.","It cannot reach beyond the original tumour site."],"meaning":"Systemic chemotherapy can affect cells in different parts of the body, including cells that have spread.","source":"Day 3 PowerPoint · slide 28"},
  {"id":"hca201a-day3-28-04","scope":"day3","topic":"Cancer treatment","term":"Chemotherapy and symptoms","prompt":"What is one symptom-related reason for giving chemotherapy?","answer":"It can reduce cancer-related symptoms by reducing tumour burden.","distractors":["It always eliminates every treatment side effect.","It directly replaces lost fluids and nutrition.","It must cure the cancer before any symptoms improve."],"meaning":"Chemotherapy can sometimes reduce symptoms even when cure is unlikely.","source":"Day 3 PowerPoint · slide 28"},
  {"id":"hca201a-day3-28-05","scope":"day3","topic":"Cancer treatment","term":"Hormone therapy mechanism","prompt":"How does hormone therapy work against hormone-sensitive cancers?","answer":"It reduces access to hormones or blocks how the cancer uses them.","distractors":["It strips away cancer cells with a surgical instrument in every case.","It acts only by heating the tumour.","It works by increasing all hormones the tumour needs."],"meaning":"Some cancers rely on particular hormones for growth. Hormone therapy interferes with that signal.","source":"Day 3 PowerPoint · slide 28"},
  {"id":"hca201a-day3-28-06","scope":"day3","topic":"Cancer treatment","term":"Hormone-suppressing drugs","prompt":"What can one type of hormone therapy drug do?","answer":"Reduce production of a hormone needed for tumour growth","distractors":["Raise the level of every hormone","Carry radiation into a single skin pore","Replace all immune cells in the body"],"meaning":"Some medications reduce hormone production. Others block a hormone's action.","source":"Day 3 PowerPoint · slide 28"},
  {"id":"hca201a-day3-28-07","scope":"day3","topic":"Cancer treatment","term":"Surgical hormone suppression","prompt":"How can surgery sometimes achieve a hormone therapy goal?","answer":"Remove an organ or gland that makes the relevant hormone","distractors":["Remove an unrelated gland to improve digestion","Use a biopsy to increase hormone production","Remove a cancer cell's nucleus without touching surrounding tissue"],"meaning":"Removing a hormone-producing organ can lower the level of hormones used by certain cancers.","source":"Day 3 PowerPoint · slide 28"},
  {"id":"hca201a-day3-29-01","scope":"day3","topic":"Cancer treatment","term":"Immunotherapy mechanism","prompt":"Which treatment helps the client's immune system fight cancer?","answer":"Immunotherapy, a form of biological therapy","distractors":["Radiotherapy","Surgery","Hormone therapy"],"meaning":"Cancer immunotherapy uses or modifies the immune response against cancer.","source":"Day 3 PowerPoint · slide 29"},
  {"id":"hca201a-day3-29-02","scope":"day3","topic":"Cancer treatment","term":"Immunotherapy and side effects","prompt":"What should a student understand about immunotherapy and side effects?","answer":"Immunotherapy can have side effects of its own, including immune reactions in healthy tissues.","distractors":["It guarantees protection against side effects from other treatments.","It cannot affect healthy tissues.","Side effects occur only when surgery is performed at the same time."],"meaning":"The slide suggests protection against side effects. NCI notes that immune activity from immunotherapy can affect healthy cells and tissues.","source":"Day 3 PowerPoint · slide 29","reference":{"label":"National Cancer Institute","url":"https://www.cancer.gov/about-cancer/treatment/types/immunotherapy/side-effects"}},
  {"id":"hca201a-day3-30-01","scope":"day3","topic":"Supporting clients with cancer","term":"Pain support","prompt":"A client with cancer says pain is keeping them from sleeping. Which care need does that directly highlight?","answer":"Pain relief and control","distractors":["Sexual well-being","Preventing bowel problems","Skin protection"],"meaning":"Acknowledge and report pain so the team can assess it and follow the care plan.","source":"Day 3 PowerPoint · slide 30"},
  {"id":"hca201a-day3-30-02","scope":"day3","topic":"Supporting clients with cancer","term":"Rest and exercise","prompt":"A client is tired after treatment and wants to remain active. Which two needs should be considered together?","answer":"Rest and exercise","distractors":["Nutrition and skin care","Spiritual support and symptom charting","Bowel support and fluid tracking"],"meaning":"Rest and activity can both support well-being. Use the client's care plan and current tolerance.","source":"Day 3 PowerPoint · slide 30"},
  {"id":"hca201a-day3-30-03","scope":"day3","topic":"Supporting clients with cancer","term":"Fluids and nutrition","prompt":"A client is eating and drinking much less than usual. Which needs does this highlight?","answer":"Fluids and nutrition","distractors":["Spiritual needs","Skin protection only","Sexual well-being"],"meaning":"Food and fluid intake are distinct needs. Observe and report changes as directed by the care plan.","source":"Day 3 PowerPoint · slide 30"},
  {"id":"hca201a-day3-30-04","scope":"day3","topic":"Supporting clients with cancer","term":"Skin breakdown","prompt":"A client spends more time in bed and needs help changing position. Which need does this directly illustrate?","answer":"Preventing skin breakdown","distractors":["Cancer screening","Maintaining social contacts","Discussing sexual concerns"],"meaning":"Reduced mobility can increase the risk of pressure-related skin damage. Follow the positioning and skin-care plan.","source":"Day 3 PowerPoint · slide 30"},
  {"id":"hca201a-day3-30-05","scope":"day3","topic":"Supporting clients with cancer","term":"Bowel problems","prompt":"A client reports fewer bowel movements and discomfort. Which category does the slide identify?","answer":"Preventing and addressing bowel problems","distractors":["Preventing skin breakdown","Supporting spiritual practices","Maintaining rest and exercise"],"meaning":"Changes in bowel habits are care concerns to observe and report.","source":"Day 3 PowerPoint · slide 30"},
  {"id":"hca201a-day3-30-06","scope":"day3","topic":"Supporting clients with cancer","term":"Treatment side effects","prompt":"A client reports new nausea after a treatment session. Which care need does this illustrate?","answer":"Recognizing and addressing treatment side effects","distractors":["Diagnosing a new tumour","Reviewing inherited risk","Screening for skin cancer"],"meaning":"New symptoms after treatment may need assessment. Report what the client says and what you observe.","source":"Day 3 PowerPoint · slide 30"},
  {"id":"hca201a-day3-30-07","scope":"day3","topic":"Supporting clients with cancer","term":"Psychological and social needs","prompt":"A client says they feel worried and miss contact with friends. Which needs are evident?","answer":"Psychological and social needs","distractors":["Skin and bowel needs","Rest and exercise only","Nutrition and hydration only"],"meaning":"Worry is a psychological concern. Losing contact with friends is a social concern.","source":"Day 3 PowerPoint · slide 30"},
  {"id":"hca201a-day3-30-08","scope":"day3","topic":"Supporting clients with cancer","term":"Spiritual needs","prompt":"A client requests time and privacy for a meaningful religious ritual. Which need are they expressing?","answer":"A spiritual need","distractors":["A bowel care need","A skin protection need","A dietary need"],"meaning":"Spiritual care can include supporting preferred practices with consent and according to the care plan.","source":"Day 3 PowerPoint · slide 30"},
  {"id":"hca201a-day3-30-09","scope":"day3","topic":"Supporting clients with cancer","term":"Sexual needs","prompt":"A client requests a private conversation about intimacy changes during treatment. Which care need does this represent?","answer":"Sexual well-being","distractors":["Skin protection","Bowel health","Rest and exercise"],"meaning":"Intimacy and sexual well-being are part of whole-person care. Respect privacy and connect the client with the appropriate team member.","source":"Day 3 PowerPoint · slide 30"}
];
